@page "/notepad"
@rendermode InteractiveServer
@inject IJSRuntime JS
@implements IAsyncDisposable

<PageTitle>Notepad</PageTitle>

<h1>Notepad</h1>

<textarea @bind="content" @bind:event="oninput" rows="12" class="form-control mb-3"
          placeholder="Type your notes here..."></textarea>

<div class="d-flex align-items-center gap-3 mb-2">
    <button class="btn btn-primary" @onclick="SaveNow">Save now</button>
    <button class="btn btn-danger" @onclick="Clear">Clear</button>
    @if (lastSavedAt is not null)
    {
        <span class="text-muted">Last saved at @lastSavedAt.Value.ToString("HH:mm:ss")</span>
    }
</div>

@code {
    private string content = string.Empty;
    private string savedContent = string.Empty;
    private DateTime? lastSavedAt;
    private IJSObjectReference? module;
    private System.Threading.Timer? autoSaveTimer;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            module = await JS.InvokeAsync<IJSObjectReference>(
                "import", Assets["Components/Pages/Notepad.razor.js"]);

            var restored = await module.InvokeAsync<string?>("load");
            if (!string.IsNullOrEmpty(restored))
            {
                content = restored;
                savedContent = restored;
                StateHasChanged();
            }

            await module.InvokeVoidAsync("registerBeforeUnload", DotNetObjectReference.Create(this));

            autoSaveTimer = new System.Threading.Timer(async _ =>
            {
                await InvokeAsync(async () =>
                {
                    if (content != savedContent)
                    {
                        await Save();
                        StateHasChanged();
                    }
                });
            }, null, TimeSpan.FromSeconds(30), TimeSpan.FromSeconds(30));
        }
    }

    [JSInvokable]
    public bool HasUnsavedChanges() => content != savedContent;

    private async Task SaveNow()
    {
        await Save();
    }

    private async Task Save()
    {
        if (module is not null)
        {
            await module.InvokeVoidAsync("save", content);
            savedContent = content;
            lastSavedAt = DateTime.Now;
        }
    }

    private async Task Clear()
    {
        content = string.Empty;
        savedContent = string.Empty;
        lastSavedAt = null;
        if (module is not null)
        {
            await module.InvokeVoidAsync("clear");
        }
    }

    public async ValueTask DisposeAsync()
    {
        if (autoSaveTimer is not null)
        {
            await autoSaveTimer.DisposeAsync();
        }
        if (module is not null)
        {
            await module.InvokeVoidAsync("dispose");
            await module.DisposeAsync();
        }
    }
}

const STORAGE_KEY = "notepad-content";

let dotNetRef = null;

export function save(content) {
    localStorage.setItem(STORAGE_KEY, content);
}

export function load() {
    return localStorage.getItem(STORAGE_KEY);
}

export function clear() {
    localStorage.removeItem(STORAGE_KEY);
}

export function registerBeforeUnload(ref) {
    dotNetRef = ref;
    window.addEventListener("beforeunload", onBeforeUnload);
}

function onBeforeUnload(e) {
    if (dotNetRef) {
        // Synchronous JS invocation isn't possible, so we check via a sync call pattern.
        // Instead, we track dirty state on the JS side by comparing with last saved.
        const saved = localStorage.getItem(STORAGE_KEY) ?? "";
        // We rely on the .NET side to tell us via the invokable method.
        // However, beforeunload must be synchronous. Use a workaround:
        // The .NET ref won't work synchronously, so we use a JS-side flag.
        if (window.__notepadDirty) {
            e.preventDefault();
        }
    }
}

export function setDirty(isDirty) {
    window.__notepadDirty = isDirty;
}

export function dispose() {
    window.removeEventListener("beforeunload", onBeforeUnload);
    window.__notepadDirty = false;
    dotNetRef = null;
}

